settings.script:
// inputProcessors() returns the list of input names (one per connected wire).
// values[id] holds the latest data from that input as a key-value object.
// Write fields on result{} to produce output from this processor.

var ids = inputProcessors();
var input = values[ids[0]];

// Pass a field through unchanged
result.temperature = input.temperature;

// Rename a field
result.pressure = input.raw_pressure;

// Add a field computed from a condition
if (input.temperature > 100) {
    result.status = "overheating";
} else {
    result.status = "normal";
}

